// runes's members: one function per member, each declared by the //kavun:member directive in its doc comment. The
// table, runesMethods, and the member entries of docs/reference/types/runes.md (alphabetical, so the order here is
// free) are generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Report truthiness, which is non-emptiness: `!!x` ⟺ `x != runes()`.
//
//kavun:member is_true pure () -> bool
func runesIsTrue(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	t, err := ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(t), nil
}

// Render the value per the [format mini-language](../../format_mini_language.md).
//
// ```go
// u"hi".format("v")   // => "u\"hi\""
// ```
//
//kavun:member format pure ([spec]) -> string
func runesFormat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return FormatWithSpec(v, id, args)
}

// Answer a copy of the elements from `start` to `end`; bounds **clamp** (contrast `splice`, which raises), negative
// indices count from the end.
//
// `slice(i, j)` **clamps** — reading past the end is harmless.
//
// ```go
// u"abcdef".slice(1, 3)           // => u"bc"
// u"abc".slice(1, 99)             // => u"bc" — clamps
// u"abcdef".slice(-3, -1)         // => u"de"
// ```
//
//kavun:member slice pure ([start[, end]]) -> runes
func runesSlice(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	s, e, err := readSliceArgs(id.String(), args)
	if err != nil {
		return Undefined, err
	}
	return v.Slice(s, e)
}

// Answer an independent, mutable copy.
//
//kavun:member copy pure () -> runes
func runesCopy(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return runesTypeCopy(v, true)
}

// Answer a deep-immutable *copy*; the source and its aliases are untouched.
//
// The copy's type name is `immutable-runes`.
//
//kavun:member freeze pure () -> runes
func runesFreeze(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return v.Freeze()
}

// Answer a new, independent, mutable copy, exactly `runes(r)` / `r.copy()`.
//
// ```go
// u"ab".runes()           // a NEW, independent, mutable copy — same as runes(r), not the receiver
// ```
//
// The `default` is taken for interface uniformity — every conversion carries it — and is never used: the
// conversion is total.
//
//kavun:member runes pure ([default]) -> runes
func runesRunes(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	c, err := runesTypeCopy(v, false)
	if err != nil {
		return Undefined, err
	}
	return ConvMember(id.String(), runesTypeName, args, true, c)
}

// Re-encode the symbols as a `string`; total.
//
// ```go
// u"héllo".string()       // => "héllo" — re-encode — total
// ```
//
// The `default` is taken for interface uniformity — every conversion carries it — and is never used: the
// conversion is total.
//
//kavun:member string pure ([default]) -> string
func runesString(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Runes)(v.Ptr)
	return ConvMember(id.String(), runesTypeName, args, true, NewStringValue(text.EncodeText(o.Elements)))
}

