// Answer the first element; an empty `runes` raises unless a default is given.
//
//kavun:member first pure ([default]) -> rune
func runesFirst(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	o := (*Runes)(v.Ptr)
	if len(args) > 1 {
		return Undefined, ErrArgCount
	}
	if len(o.Elements) == 0 {
		return emptySeqResult(name, args)
	}
	return RuneValue(o.Elements[0]), nil
}

