// Map every symbol to lowercase.
//
// ```go
// u"héllo".upper()                // => u"HÉLLO"
// u"HÉLLO".lower()                // => u"héllo"
// ```
//
//kavun:member lower pure () -> runes
func runesLower(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Runes)(v.Ptr)
	rs := make([]rune, len(o.Elements))
	for i, r := range o.Elements {
		rs[i] = unicode.ToLower(r)
	}
	return NewRunesValue(rs, false), nil
}

// Map every symbol to uppercase; see [`lower`](#lower).
//
//kavun:member upper pure () -> runes
func runesUpper(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Runes)(v.Ptr)
	rs := make([]rune, len(o.Elements))
	for i, r := range o.Elements {
		rs[i] = unicode.ToUpper(r)
	}
	return NewRunesValue(rs, false), nil
}

// Report whether an element, a run, a member of a set or a predicate match occurs; with no argument, whether any
// element is significant.
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// `contains` takes the full menu: element, run, homogeneous variadic set, predicate, or absent.
// `contains(fn)` ≡ `any(fn)` and `contains()` ≡ `any()` — the two named synonyms.
//
// ```go
// u"héllo".contains("éll")                        // => true
// u"abc".contains('x', 'b')                       // => true — set: ∈ {'x','b'}
// u"abcd".contains("xy", "cd")                    // => true — run set
// u"abc".contains(func(r) { return r > 'b' })     // => true
// ```
//
//kavun:member contains pure (...x) -> bool
func runesContains(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	// The empty run is contained everywhere, the same answer `in` gives.
	m, err := runesReadMatchArgs(vm, "contains", args, false)
	if err != nil {
		return Undefined, err
	}
	elems := (*Runes)(v.Ptr).Elements

	if m.runs != nil {
		for _, r := range m.runs {
			if len(r) == 0 {
				return True, nil
			}
		}
		for i := range elems {
			if seq.RunLengthAt(elems, i, m.runs) > 0 {
				return True, nil
			}
		}
		return False, nil
	}

	for i, r := range elems {
		hit, err := m.matches(i, r)
		if err != nil {
			return Undefined, err
		}
		if hit {
			return True, nil
		}
	}
	return False, nil
}

// Count the matches of an element, a run (non-overlapping occurrences), a set or a predicate; with no argument, the
// significant elements.
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// ```go
// u"banana".count('a')                            // => 3
// u"banana".count("an")                           // => 2 — non-overlapping
// u"banana".count('a', 'b')                       // => 4 — set
// ```
//
//kavun:member count pure (...x) -> int
func runesCount(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	m, err := runesReadMatchArgs(vm, "count", args, false)
	if err != nil {
		return Undefined, err
	}
	elems := (*Runes)(v.Ptr).Elements

	n := int64(0)
	if m.runs != nil {
		for i := 0; i < len(elems); {
			if k := seq.RunLengthAt(elems, i, m.runs); k > 0 {
				n++
				i += k
			} else {
				i++
			}
		}
		return IntValue(n), nil
	}

	for i, r := range elems {
		hit, err := m.matches(i, r)
		if err != nil {
			return Undefined, err
		}
		if hit {
			n++
		}
	}
	return IntValue(n), nil
}

// Keep only the matches of an element, a run, a set or a predicate; with no argument, the significant elements; see
// [`remove`](#remove).
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
//kavun:member keep pure (...x) -> runes
func runesKeep(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := runesKept(vm, "keep", v, args)
	if err != nil {
		return Undefined, err
	}
	return NewRunesValue(out, false), nil
}

// In-place twin of `keep`.
//
//kavun:member keep_in_place impure (...x) -> runes
func runesKeepInPlace(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	const name = "keep_in_place"
	if v.Immutable {
		return Undefined, errs.NewNotMutableError(name, v.TypeName())
	}
	out, err := runesKept(vm, name, v, args)
	if err != nil {
		return Undefined, err
	}
	(*Runes)(v.Ptr).Set(out)
	return v, nil
}

// Remove every match of an element, a run, a set or a predicate; with no argument, the elements of the
// [blank set](#the-blank-set).
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// Both take the full menu and act on **every** occurrence, in the direction their names give: `keep(x)` answers
// what matches, `remove(x)` answers what does not. With no argument each reads against the blank set as its own
// verb implies: `keep()` keeps the significant symbols, `remove()` removes the blank ones — the same answer by
// two different actions. A miss is a silent no-op.
//
// ```go
// u"banana".keep('a')                           // => u"aaa"
// u"banana".remove("an")                          // => u"ba"
// u"banana".remove('a', 'b')                      // => u"nn"
// u"abcdef".keep(func(i, r) { return i % 2 == 0 })   // => u"ace" — two-parameter form: (index, element)
// ```
//
//kavun:member remove pure (...x) -> runes
func runesRemove(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := runesRemaining(vm, "remove", v, args)
	if err != nil {
		return Undefined, err
	}
	return NewRunesValue(out, false), nil
}

// In-place twin of `remove`.
//
//kavun:member remove_in_place impure (...x) -> runes
func runesRemoveInPlace(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	const name = "remove_in_place"
	if v.Immutable {
		return Undefined, errs.NewNotMutableError(name, v.TypeName())
	}
	out, err := runesRemaining(vm, name, v, args)
	if err != nil {
		return Undefined, err
	}
	(*Runes)(v.Ptr).Set(out)
	return v, nil
}

// Report whether some element matches a value, a set or a predicate; with no argument, whether any element is
// significant.
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
// `any`/`all` take a value, a function, or nothing; a run argument raises (there is no universal reading for "all of
// a run").
//
// ```go
// u"abc".any(func(r) { return r == 'c' })         // => true
// u"abc".all(func(r) { return r >= 'a' })         // => true
// u"abc".any("bc")                                // Error: invalid_argument_type — run: that query is contains's
// ```
//
//kavun:member any pure (...x) -> bool
func runesAny(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	m, err := runesReadMatchArgs(vm, "any", args, true)
	if err != nil {
		return Undefined, err
	}
	for i, r := range (*Runes)(v.Ptr).Elements {
		hit, err := m.matches(i, r)
		if err != nil {
			return Undefined, err
		}
		if hit {
			return True, nil
		}
	}
	return False, nil
}

// Report whether every element matches a value, a set or a predicate; with no argument, whether every element is
// significant; see [`any`](#any).
//
// A function argument gets the element, or `(index, element)` when it does not accept one argument
// ([callbacks](#callbacks)).
//
//kavun:member all pure (...x) -> bool
func runesAll(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	// True on empty runes.
	m, err := runesReadMatchArgs(vm, "all", args, true)
	if err != nil {
		return Undefined, err
	}
	for i, r := range (*Runes)(v.Ptr).Elements {
		hit, err := m.matches(i, r)
		if err != nil {
			return Undefined, err
		}
		if !hit {
			return False, nil
		}
	}
	return True, nil
}

// Sort the symbols by code point; there is no comparator.
//
// ```go
// u"cba".sort()                   // => u"abc"
// ```
//
//kavun:member sort pure () -> runes
func runesSort(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Runes)(v.Ptr)
	sorted := make([]rune, len(o.Elements))
	copy(sorted, o.Elements)
	slices.Sort(sorted)
	return NewRunesValue(sorted, false), nil
}

// In-place twin of `sort`.
//
//kavun:member sort_in_place impure () -> runes
func runesSortInPlace(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	o := (*Runes)(v.Ptr)
	if v.Immutable {
		return Undefined, errs.NewNotMutableError(name, v.TypeName())
	}
	slices.Sort(o.Elements)
	return v, nil
}

// Collapse each run of equal neighbours to one element.
//
// ```go
// u"aabbaa".dedup()               // => u"aba"
// ```
//
//kavun:member dedup pure () -> runes
func runesDedup(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	return NewRunesValue(runesDeduped((*Runes)(v.Ptr).Elements), false), nil
}

// In-place twin of `dedup`.
//
//kavun:member dedup_in_place impure () -> runes
func runesDedupInPlace(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	const name = "dedup_in_place"
	if v.Immutable {
		return Undefined, errs.NewNotMutableError(name, v.TypeName())
	}
	o := (*Runes)(v.Ptr)
	o.Set(runesDeduped(o.Elements))
	return v, nil
}

