// Fold the elements left to right into an accumulator that starts at `init`.
//
// `reduce(init, fn)` folds with the accumulator first. The callback gets `(acc, element)`, or `(acc, index,
// element)` when it does not accept two arguments ([callbacks](#callbacks)).
//
// ```go
// u"abc".reduce(0, func(acc, r) { return acc + r.int() })  // => 294
// u"ab".reduce(u"".copy(), func(acc, r) { return acc.append(r, r) })  // => u"aabb"
// ```
//
//kavun:member reduce pure (init, fn) -> value
func runesReduce(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	acc, cb, err := readReduceArgs(vm, args)
	if err != nil {
		return Undefined, err
	}
	for i, e := range (*Runes)(v.Ptr).Elements {
		acc, err = cb.Call(acc, i, RuneValue(e))
		if err != nil {
			return Undefined, err
		}
	}
	return acc, nil
}

// Concatenate the receiver with itself `n` times; `u * n` is the operator form.
//
// `repeat(n)` takes a whole-number count (`2.0` converts, `1.5` raises) and has the operator form `u * n` (no
// reflected `n * u`).
//
// ```go
// u"ab".repeat(2)                 // => u"abab"
// u"ab".repeat(1.5)               // Error: invalid_value — never silent truncation
// ```
//
//kavun:member repeat pure (n) -> runes
func runesRepeat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	name := id.String()
	o := (*Runes)(v.Ptr)
	n, err := parseRepeatCount(name, args)
	if err != nil {
		return Undefined, err
	}
	src := o.Elements
	sl := len(src)
	total, err := seq.RepeatTotal(name, n, sl)
	if err != nil {
		return Undefined, err
	}
	out := make([]rune, total)
	// step by the receiver's length, never by the count: an empty receiver has total 0 and must not
	// spin n times copying nothing
	for i := 0; i < total; i += sl {
		copy(out[i:], src)
	}
	return NewRunesValue(out, false), nil
}

// Split the text into an array of the pieces between the separators.
//
// Separators come from the dispatch menu: element, run, homogeneous variadic set, element-level predicate, or
// absent (= the blank set). **Explicit separators keep empty pieces** — n hits produce n+1 pieces; the no-arg
// blank form separates on runs of whitespace and drops empties. An empty-run separator matches nothing. There
// is **no limit argument**. The pieces are `runes`.
//
// ```go
// u"a,,b".split(',')              // => [u"a", u"", u"b"] — empties kept
// u"a::b::c".split("::")          // => [u"a", u"b", u"c"]
// u"a,b;c".split(',', ';')        // => [u"a", u"b", u"c"] — element set
// u"a,b;c".split(',', "::")       // Error: invalid_argument_type — mixed element + run set
// u"a1b2c".split(func(r) { return r >= '0' && r <= '9' })  // => [u"a", u"b", u"c"]
// u"  a b \t c ".split()          // => [u"a", u"b", u"c"] — blank separators, empties dropped
// u"ab".split("")                 // => [u"ab"] — an empty run matches nothing
// ```
//
//kavun:member split pure (...seps) -> array
func runesSplit(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	const name = "split"
	elems := (*Runes)(v.Ptr).Elements

	if len(args) == 0 {
		var pieces []Value
		start := -1
		for i, e := range elems {
			if text.IsBlankRune(e) {
				if start >= 0 {
					pieces = append(pieces, runesPiece(elems[start:i]))
					start = -1
				}
			} else if start < 0 {
				start = i
			}
		}
		if start >= 0 {
			pieces = append(pieces, runesPiece(elems[start:]))
		}
		return NewArrayValue(pieces, false), nil
	}

	pieces := make([]Value, 0, 4)
	start := 0

	if args[0].IsCallable() {
		if len(args) > 1 {
			return Undefined, seq.ErrPredicateAmongMany(name)
		}
		cb, err := newElemCallback(vm, name, args[0])
		if err != nil {
			return Undefined, err
		}
		for i, e := range elems {
			res, err := cb.Call(i, RuneValue(e))
			if err != nil {
				return Undefined, err
			}
			hit, err := res.IsTrue()
			if err != nil {
				return Undefined, err
			}
			if hit {
				pieces = append(pieces, runesPiece(elems[start:i]))
				start = i + 1
			}
		}
		pieces = append(pieces, runesPiece(elems[start:]))
		return NewArrayValue(pieces, false), nil
	}

	runs, err := runesReadRunSet(name, args, "one reading per call (a function among several arguments always raises)")
	if err != nil {
		return Undefined, err
	}
	for i := 0; i < len(elems); {
		if k := seq.RunLengthAt(elems, i, runs); k > 0 {
			pieces = append(pieces, runesPiece(elems[start:i]))
			i += k
			start = i
		} else {
			i++
		}
	}
	pieces = append(pieces, runesPiece(elems[start:]))
	return NewArrayValue(pieces, false), nil
}

// Split the text into an array of its lines at `\n`, `\r\n` or `\r`; a trailing line break adds no empty last line.
//
// ```go
// u"a\nb\r\nc".split_lines()      // => [u"a", u"b", u"c"]
// u"a\n\nb".split_lines()         // => [u"a", u"", u"b"] — interior empty lines kept
// ```
//
//kavun:member split_lines pure () -> array
func runesSplitLines(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	const name = "split_lines"
	o := (*Runes)(v.Ptr)
	pieces := text.SplitLinesString(text.EncodeText(o.Elements))
	arr := make([]Value, len(pieces))
	for i, p := range pieces {
		arr[i] = NewRunesValue(text.DecodeText(p), false)
	}
	return NewArrayValue(arr, false), nil
}

// Split at the first separator hit into exactly three pieces, `[before, sep, after]`.
//
// `partition` splits at the **first** hit into `[before, separator, after]`; a miss answers `[r, u"", u""]`. With
// no argument the separator is the whole first maximal run of blank filler. Separators take the same menu as
// [`split`](#split); the pieces are `runes`.
//
// ```go
// u"key=value=x".partition("=")   // => [u"key", u"=", u"value=x"]
// ```
//
//kavun:member partition pure (...seps) -> array
func runesPartition(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	// The separator at the first hit is the longest run at that position.
	const name = "partition"
	elems := (*Runes)(v.Ptr).Elements
	found, n := -1, 0

	switch {
	case len(args) == 0:
		for i, e := range elems {
			if text.IsBlankRune(e) {
				found, n = i, 1
				for found+n < len(elems) && text.IsBlankRune(elems[found+n]) {
					n++
				}
				break
			}
		}

	case args[0].IsCallable():
		if len(args) > 1 {
			return Undefined, seq.ErrPredicateAmongMany(name)
		}
		cb, err := newElemCallback(vm, name, args[0])
		if err != nil {
			return Undefined, err
		}
		for i, e := range elems {
			res, err := cb.Call(i, RuneValue(e))
			if err != nil {
				return Undefined, err
			}
			hit, err := res.IsTrue()
			if err != nil {
				return Undefined, err
			}
			if hit {
				found, n = i, 1
				break
			}
		}

	default:
		runs, err := runesReadRunSet(name, args, "one reading per call (a function among several arguments always raises)")
		if err != nil {
			return Undefined, err
		}
		for i := range elems {
			if k := seq.RunLengthAt(elems, i, runs); k > 0 {
				found, n = i, k
				break
			}
		}
	}

	if found < 0 {
		return NewArrayValue([]Value{runesPiece(elems), runesPiece(nil), runesPiece(nil)}, false), nil
	}
	return NewArrayValue([]Value{runesPiece(elems[:found]), runesPiece(elems[found : found+n]), runesPiece(elems[found+n:])}, false), nil
}

// Repeatedly drop the elements at both ends while they belong to the set (the blank set with no argument).
//
// The trim family takes a **set of elements** and strips while members of the set repeat at the edge. A run
// argument raises — the anchored run form is `remove_prefix`/`remove_suffix`. No arguments = the blank set.
//
// ```go
// u"xxhixx".trim('x')             // => u"hi"
// u"xyhixy".trim('x', 'y')        // => u"hi"
// u"xyhixy".trim("xy")            // Error: invalid_argument_type: trim takes a set of elements, not a run
// u"  hi  ".trim_start()          // => u"hi  "
// u"  hi  ".trim_end()            // => u"  hi"
// ```
//
//kavun:member trim pure (...set) -> runes
func runesTrim(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := runesTrimmed("trim", v, args, true, true)
	if err != nil {
		return Undefined, err
	}
	return NewRunesValue(out, false), nil
}

// In-place twin of `trim`.
//
//kavun:member trim_in_place impure (...set) -> runes
func runesTrimInPlace(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	const name = "trim_in_place"
	if v.Immutable {
		return Undefined, errs.NewNotMutableError(name, v.TypeName())
	}
	out, err := runesTrimmed(name, v, args, true, true)
	if err != nil {
		return Undefined, err
	}
	(*Runes)(v.Ptr).Set(out)
	return v, nil
}

