// Report whether the `runes` value starts with the element or run, or with any of a set of them.
//
// The prefix/suffix tests take an element, a run, or a variadic run set — no predicate, no absent form ("first
// symbol satisfies f" is `index(f) == 0`).
//
// ```go
// u"foobar".has_prefix("foo")             // => true
// u"foobar".has_prefix('f')               // => true
// u"foobar".has_prefix("bar", "foo")      // => true — set
// ```
//
//kavun:member has_prefix pure (x, ...more) -> bool
func runesHasPrefix(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	best, err := runesAnchoredRun("has_prefix", v, args, false)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(best >= 0), nil
}

// Report whether the `runes` value ends with the element or run, or with any of a set of them; see
// [`has_prefix`](#has_prefix).
//
//kavun:member has_suffix pure (x, ...more) -> bool
func runesHasSuffix(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	best, err := runesAnchoredRun("has_suffix", v, args, true)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(best >= 0), nil
}

// Remove the element or run — or the longest of a set of them — once, anchored at the front; absent → unchanged.
//
// The removals take an element or run — of a set, the longest that matches — remove it **once**, and answer the
// receiver unchanged on a miss.
//
// ```go
// u"foobar".remove_prefix("foo")          // => u"bar"
// u"foobar".remove_prefix("bar")          // => u"foobar" — miss → unchanged
// u"foobar".remove_suffix("bar")          // => u"foo"
// u"abcd".remove_prefix("ab", "abc")      // => u"d" — longest run wins the tie
// ```
//
//kavun:member remove_prefix pure (x, ...more) -> runes
func runesRemovePrefix(_ VM, v Value, _ member.ID, args []Value) (Value, error) {
	// The longest matching prefix is removed, once.
	out, err := runesWithoutAnchored("remove_prefix", v, args, false)
	if err != nil {
		return Undefined, err
	}
	return NewRunesValue(out, false), nil
}

